    console.log(`[daemon] Port file written: ${port}`);
  }

  // Initialize WebSocket managers
  pubsubManager = new PubSubManager();
  heartbeatManager = new HeartbeatManager();
  wsHandler = new WebSocketHandler(pubsubManager);

